        // both pixels' fetches first: colours, then (temporal blocks) both motion taps and both 5-tap histories in one
        // straight block, so the second pixel's chain overlaps the first's (the default waits for each pixel in turn)
        const bool temporal = !NO_TEMPORAL && hist != 0ull && mot != 0ull;
        F4 colp[2], hsp[2];
        float xnp[2], ynp[2], hnp[2];
#pragma unroll
        for (u32 i = 0; i < 2; ++i) {
            const u32 idx = lane + 32u * i, r = idx >> 3, c = idx & 7u;
            const int y = y0 + (int)r, x = x0 + (int)c;
            const int ym = y < frows ? y : 2 * frows - y - 2, xm = x < fcols ? x : 2 * fcols - x - 2;
            xnp[i] = __fdividef((float)xm + 0.5f, fc);
            ynp[i] = __fdividef((float)ym + 0.5f, fr);
            colp[i] = tex_rgba(tex, P_F32(156) * fmaf(xnp[i], P_F32(148), P_F32(140)), P_F32(160) * fmaf(ynp[i], P_F32(152), P_F32(144)));
        }
        if (temporal) {
            F4 mvp[2];
#pragma unroll
            for (u32 i = 0; i < 2; ++i)
                mvp[i] = tex_rgba(mot, P_F32(84) * fmaf(xnp[i], P_F32(76), P_F32(68)), P_F32(88) * fmaf(ynp[i], P_F32(80), P_F32(72)));
#pragma unroll
            for (u32 i = 0; i < 2; ++i)
                history5(hist, fmaf(mvp[i].x, P_F32(164), xnp[i]), fmaf(mvp[i].y, P_F32(168), ynp[i]), fc, fr, fc - 0.5f, fr - 0.5f,
                         rcfc, rcfr, P_F32(52), P_F32(44), P_F32(60), P_F32(56), P_F32(48), P_F32(64), hsp[i], hnp[i]);
        }
#endif
#pragma unroll
        for (u32 i = 0; i < 2; ++i) {
            const u32 idx = lane + 32u * i, r = idx >> 3, c = idx & 7u;
            const int y = y0 + (int)r, x = x0 + (int)c;
#if TEMPORAL_PAIR
            const F4 col = colp[i];
            const u32 cr = centred(col.x, cscale), cg = centred(col.y, cscale), cb = centred(col.z, cscale);
            u32 hr = cr, hg = cg, hb = cb;
