            u32 n01 = 0u, n2 = 0u;
#if DBG_STAGE != 3
            {
                const u32 base = ((u32)x * 0x8DA6B343u) ^ seedmix ^ ((u32)y * 0xD8163841u) ^ 0x243F6A88u;
                const u32 t0 = pcg(base), h = (t0 >> 22) ^ t0;
                const float ua = unit24(h * 0x2C9277B5u + 0xAC564B05u), ub = unit24(h * 0xFA6DC5F9u + 0x4712A88Eu);
                const float uc = unit24(h * 0xCAA5B80Du + 0x21DD796Bu), ud = unit24(h * 0x83232C31u + 0x3463E0ACu);
                const float ra = sqrta(lg2a(ua) * 0.693147182464599609f * -2.0f), rc = sqrta(lg2a(uc) * 0.693147182464599609f * -2.0f);
