            const V4 lo = {n01, n2, cr | (cg << 16), cb | (hr << 16)};                   // n0 n1 n2 1 R G B R'
            const V4 hi = {hg | (hb << 16), cond0, cond1, cond2};                        // G' B' style tone structure skin other 0
            *(V4*)(sm_qb + (16u * s + m) * 32u) = lo;
            *(V4*)(sm_qb + (16u * s + m) * 32u + 16u) = hi;
        }
        if (lane < 16u) *(V4*)(sm_qb + QBYTES + lane * 16u) = V4{0u, 0u, 0u, 0u};        // the lift's scale words
        __syncwarp();
    }
    const bool lift4 = (p.options & OPT_LIFT4) != 0u;
    const u8* const wlift16 = rec + O[R_LIFT16];
    const u8* const wlift4 = rec + O[R_LIFT4];
#else
    const u8* const xin = (const u8*)P_U64(0);
    const u8* const skin = (const u8*)P_U64(8);
    const int hH = (H + 1) >> 1, hW = (W + 1) >> 1, vr = (hH + 3) & ~3, vc = (hW + 3) & ~3;
    const float* const mgain = (const float*)(rec + O[O_GAIN] + t * 32u);
    const float* const sgain = (const float*)(rec + O[R_SGAIN] + t * 32u);
    const u32 mg16[4] = {h2_pack(mgain[0], mgain[1]), h2_pack(mgain[2], mgain[3]), h2_pack(mgain[4], mgain[5]), h2_pack(mgain[6], mgain[7])};
    const u32 sg16[4] = {h2_pack(sgain[0], sgain[1]), h2_pack(sgain[2], sgain[3]), h2_pack(sgain[4], sgain[5]), h2_pack(sgain[6], sgain[7])};
#endif
#pragma unroll
    for (u32 s = 0; s < 4; ++s) {
        u32 hv[2][4];                                           // x of tokens g, g + 8: channels 8 j + 2 t + e as float16 pairs
#if BLOCK == 1
        const u8* const frow0 = sm_qb + (16u * s + g) * 32u;    // the feature rows of tokens g and g + 8
        const u8* const frow1 = frow0 + 8u * 32u;
#if DBG_STAGE == 3
#pragma unroll
        for (u32 j = 0; j < 4; ++j) {
            hv[0][j] = *(const u32*)(frow0 + 8u + 4u * (j & 1u));
            hv[1][j] = *(const u32*)(frow1 + 8u + 4u * (j & 1u));
        }
#else
        if (!lift4) {
            // NVIDIA's product: A = features (k = 2 t, 2 t + 1 | + 8), B = the library's float16 slices, float32 accumulator
            const u32 a0 = *(const u32*)(frow0 + 4u * t), a1 = *(const u32*)(frow1 + 4u * t);
            const u32 a2 = *(const u32*)(frow0 + 16u + 4u * t), a3 = *(const u32*)(frow1 + 16u + 4u * t);
#pragma unroll
            for (u32 j = 0; j < 4; ++j) {
                const u64 b = *(const u64*)(wlift16 + 2u * ((j >> 1) * 256u + 32u * g + 8u * t + 4u * (j & 1u)));
                // float16 accumulator from zero, as NVIDIA's (F0 15467-15572: m16n8k16 .f16.f16.f16.f16, C = 0);
                // a float32 accumulator rounded afterwards differs in about 1 code in 3.4 million (round 2)
                u32 c[2] = {0u, 0u};
                mma16_f16(c, a0, a1, a2, a3, (u32)b, (u32)(b >> 32));
                hv[0][j] = c[0];
                hv[1][j] = c[1];
            }
        } else {
            // 4-bit: lanes t = 0, 1 pack features 8 (t & 1) .. + 7 (K 0-15), lanes 2, 3 their second term (K 16-31)
            const float tl = F[R_TL];
            const float* const fac = (const float*)(wlift4 + SLAB) + 8u * (t & 1u);
            float v[2][8];
#pragma unroll
            for (u32 rh = 0; rh < 2; ++rh) {
                const V4 f = *(const V4*)((rh ? frow1 : frow0) + 16u * (t & 1u));
                const u32 fw[4] = {f.x, f.y, f.z, f.w};
#pragma unroll
                for (u32 i = 0; i < 4; ++i) {
                    float lo, hi;
                    h2_unpack(fw[i], lo, hi);
                    v[rh][2 * i] = lo * (fac[2 * i] * tl);
                    v[rh][2 * i + 1] = hi * (fac[2 * i + 1] * tl);
                }
            }
            u32 w0, w1;
            const u32 codes = lift_pack(v, t >= 2u, (p.options & OPT_TWO_L) != 0u, w0, w1);
            m_put_scale(sm_qb + QBYTES + s * 64u, g, t, 0u, codes);
            __syncwarp();
            const u32 sa = *(const u32*)(sm_qb + QBYTES + s * 64u + g * 8u + (t & 1u) * 4u);
            const V4 a = {w0, w1, 0u, 0u};
            const V4 n01 = *(const V4*)(wlift4 + lane * 16u), n23 = *(const V4*)(wlift4 + 512u + lane * 16u);
            const V4 sw = *(const V4*)(wlift4 + 1024u + g * 16u);
            float acc[1][4][4];
            ZERO_ACC(acc, 1, 4)
            mma4(acc[0][0], a, n01.x, n01.y, sa, sw.x); mma4(acc[0][1], a, n01.z, n01.w, sa, sw.y);
            mma4(acc[0][2], a, n23.x, n23.y, sa, sw.z); mma4(acc[0][3], a, n23.z, n23.w, sa, sw.w);
            const float sl = F[R_SL];
#pragma unroll
            for (u32 j = 0; j < 4; ++j) {
                hv[0][j] = h2_pack(acc[0][j][0] * sl, acc[0][j][1] * sl);
                hv[1][j] = h2_pack(acc[0][j][2] * sl, acc[0][j][3] * sl);
            }
        }
#endif
#else
        // post-block: up = the half-size main input replicated 2x (view layout), skip = encoder skip (tile layout)
        {
            u32 up[2][4], sk[2][4];
#pragma unroll
            for (u32 rh = 0; rh < 2; ++rh) {
                const u32 m = g + 8u * rh;
                const int py = (ty0 + (int)(s >> 1)) * 4 + (int)(m >> 2), px = (tx0 + (int)(s & 1u)) * 4 + (int)(m & 3u);
                const int cy = min(py >> 1, hH - 1), cx = min(px >> 1, hW - 1);
                const bool in = inside[s] && py >= 0 && px >= 0;
#pragma unroll
                for (u32 a = 0; a < 2; ++a) {
                    const u64 at = ((u64)(u32)((int)a * vr + (in ? cy : 0)) * (u32)vc + (u32)(in ? cx : 0)) * 16u + t * 4u;
                    const u32 word = in ? load_cg32(xin + at) : 0u;
                    m_e4m3x4_to_h2(word, up[rh][2 * a], up[rh][2 * a + 1]);
                }
            }
            const V4 skw = inside[s] ? load_cg(skin + tile_at[s]) : V4{0u, 0u, 0u, 0u};
            m_e4m3x4_to_h2(skw.x, sk[0][0], sk[0][1]); m_e4m3x4_to_h2(skw.y, sk[1][0], sk[1][1]);
            m_e4m3x4_to_h2(skw.z, sk[0][2], sk[0][3]); m_e4m3x4_to_h2(skw.w, sk[1][2], sk[1][3]);
#pragma unroll
            for (u32 rh = 0; rh < 2; ++rh)
#pragma unroll
                for (u32 j = 0; j < 4; ++j)                         // f16(skip * sg + f16(up * mg)), as NVIDIA's kernel (lab: bit-exact)
                    hv[rh][j] = inside[s] ? h2_fma(sk[rh][j], sg16[j], h2_mul(up[rh][j], mg16[j])) : 0u;
        }
#endif
#pragma unroll
        for (u32 rh = 0; rh < 2; ++rh) {                        // the residual reads float16 values
            const V4 wide = {hv[rh][0], hv[rh][1], hv[rh][2], hv[rh][3]};
            *(V4*)(sm_x + ((s * 2u + rh) * 32u + lane) * 16u) = wide;
        }
#if BODY_STAGE == 0
        {
            u32 xp[2][4];                                       // what the expansion packs: x, or e4m3(x) (OPT_X8)
            const bool x8 = (p.options & OPT_X8) != 0u;
#pragma unroll
            for (u32 rh = 0; rh < 2; ++rh)
#pragma unroll
                for (u32 j = 0; j < 4; ++j) xp[rh][j] = x8 ? h2_e4m3_round(hv[rh][j]) : hv[rh][j];
            u32 n0, n1, e0, e1, codes2;
            const u32 codes = m_pack2_h_two(xp[0], xp[1], F[F_TX], n0, n1, e0, e1, codes2, (p.options & OPT_TWO_X) != 0u);
            const V4 q = {n0, n1, e0, e1};
            *(V4*)(sm_qa + s * 512u + lane * 16u) = q;
            m_put_scale(sm_qa + QBYTES + s * 64u, g, t, 0u, codes);
            m_put_scale(sm_qa + QBYTES + s * 64u, g, t, 1u, codes2);
        }
#endif
    }
    __syncwarp();


#pragma unroll
    for (u32 s=0;s<4;s++) {
        const V4 a=*(const V4*)(sm_x+((s*2)*32+lane)*16);
        const V4 b=*(const V4*)(sm_x+((s*2+1)*32+lane)*16);
        *(V4*)(pair_window+s*512+lane*16)=V4{
            att_h2x2_to_e4m3x4(a.x,a.y),att_h2x2_to_e4m3x4(b.x,b.y),
            att_h2x2_to_e4m3x4(a.z,a.w),att_h2x2_to_e4m3x4(b.z,b.w)};
    }
    } // warp zero input
    __syncthreads();
    const u32* U=(const u32*)P.mix;
#pragma unroll 1
    for (int stage=0;stage<(PREFIX_ONLY ? 0 : STAGES);stage++) {
        Pair::Params q={};q.w=P.mix+U[8+stage];q.options=U[16+stage];
        Pair::body_stage(q,pair_window);
        __syncthreads();
    }
#if ASTRA_DIAG
    if(blockIdx.x+gridDim.x*blockIdx.y==P.pad) {
        u8* dst=(u8*)P_U64(24);
        for(int word=threadIdx.y*32+lane;word<512;word+=64)
            ((u32*)dst)[word]=((u32*)pair_window)[word];
    }
#endif
    if(threadIdx.y==0) {
    u32 o16[4][2][4];
#pragma unroll
    for(u32 s=0;s<4;s++) {
        const V4 a=*(const V4*)(pair_window+s*512+lane*16);
        m_e4m3x4_to_h2(a.x,o16[s][0][0],o16[s][0][1]);
        m_e4m3x4_to_h2(a.y,o16[s][1][0],o16[s][1][1]);
        m_e4m3x4_to_h2(a.z,o16[s][0][2],o16[s][0][3]);
        m_e4m3x4_to_h2(a.w,o16[s][1][2],o16[s][1][3]);
    }
#if BLOCK == 1
    // ---- pre-block outputs: e4m3(o) in tile layout (+224); 2x2 mean of o in view layout (+256) ------------------
    {
        u8* const skip_out = (u8*)P_U64(224);
#pragma unroll
        for (u32 s = 0; s < 4; ++s)
            if (inside[s]) {
                const V4 packed = {att_h2x2_to_e4m3x4(o16[s][0][0], o16[s][0][1]), att_h2x2_to_e4m3x4(o16[s][1][0], o16[s][1][1]),
                                   att_h2x2_to_e4m3x4(o16[s][0][2], o16[s][0][3]), att_h2x2_to_e4m3x4(o16[s][1][2], o16[s][1][3])};
                *(V4*)(skip_out + tile_at[s]) = packed;
            }
        // swin4.cu's butterfly: column pairs (lane ^ 4), then row pairs (lane ^ 16), float16 additions, times 0.25
        const u32 ci = (g & 1u) + 2u * (g >> 2);
        const bool b2 = (g & 1u) != 0u, b4 = (g >> 2) != 0u;
        u32 pool[2][4];
#pragma unroll
        for (u32 rh = 0; rh < 2; ++rh)
#pragma unroll
            for (u32 j = 0; j < 4; ++j) {
                u32 k0 = b2 ? o16[1][rh][j] : o16[0][rh][j];
                u32 k1 = b2 ? o16[3][rh][j] : o16[2][rh][j];
                const u32 s0 = b2 ? o16[0][rh][j] : o16[1][rh][j];
                const u32 s1 = b2 ? o16[2][rh][j] : o16[3][rh][j];
                k0 = h2_add(k0, __shfl_xor_sync(0xffffffffu, s0, 4));
                k1 = h2_add(k1, __shfl_xor_sync(0xffffffffu, s1, 4));
                const u32 a = h2_add(b4 ? k1 : k0, __shfl_xor_sync(0xffffffffu, b4 ? k0 : k1, 16));
                pool[rh][j] = h2_mul(a, 0x34003400u);
            }
        u8* const pooled = (u8*)P_U64(256);
        const int pr = P_S32(264), pc = P_S32(268), hH = H >> 1, hW = W >> 1;
        const int px = (x0 >> 1) + (int)((ci & 1u) * 2u + ((g >> 1) & 1u));
#pragma unroll
        for (u32 rh = 0; rh < 2; ++rh) {
            const int py = (y0 >> 1) + (int)((ci >> 1) * 2u + rh);
            if (py >= 0 && py < hH && px >= 0 && px < hW) {
#pragma unroll
                for (u32 a = 0; a < 2; ++a)
                    *(u32*)(pooled + ((u64)(u32)((int)a * pr + py) * (u32)pc + (u32)px) * 16u + t * 4u) =
                        att_h2x2_to_e4m3x4(pool[rh][2 * a], pool[rh][2 * a + 1]);
            }
        }
    }

#else
    } // the old warp-zero output scope; all threads own one post pixel below
    {
        const int lx=lane&7,ly=4*threadIdx.y+(lane>>3),px=x0+lx,py=y0+ly;
        const u64 surf=P_U64(16),tex=P_U64(56),hist=P_U64(88),mot=P_U64(96),bscale=P_U64(104);
        const int fcols=P_S32(172),frows=P_S32(176);
        const bool final_clamp=P_S32(52)!=0;
        const float rw=P_F32(48);
        const u16* weights=(const u16*)(rec+O[R_PROJ16]);
        float acc[4]={0,0,0,0};
#if !COPY_IO
#pragma unroll
        for(int step=0;step<2;step++) {
#pragma unroll
            for(int q=0;q<4;q++) {
                float v[4];Pair::decode(*(u32*)(pair_window+Pair::at(ly,lx,0,q,8)+step*8),v);
#pragma unroll
                for(int j=0;j<4;j++) {
                    const int ch=16*step+2*q+(j&1)+8*(j>>1);
#pragma unroll
                    for(int colour=0;colour<4;colour++) acc[colour]=fmaf(v[j],h16_to_f32(weights[colour*32+ch]),acc[colour]);
                }
            }
#pragma unroll
            for(int colour=0;colour<4;colour++) { u16 h;asm("cvt.rn.f16.f32 %0, %1;":"=h"(h):"f"(acc[colour]));acc[colour]=h16_to_f32(h); }
        }
#endif
        const float r0=acc[0],r1=acc[1],r2=acc[2],r3=acc[3];
        if(px>=0 && py>=0 && px<W && py<H && px<fcols && py<frows) {
                float v0, v1, v2, alpha = 0.0f;
                const float xn = __fdividef((float)px + 0.5f, (float)fcols), yn = __fdividef((float)py + 0.5f, (float)frows);
                if (tex != 0ull) {
#if TEMPORAL_PAIR
                    const F4 f = colp[pass];
#else
                    const float u = P_F32(80) * fmaf(P_F32(72), xn, P_F32(64));
                    const float v = P_F32(84) * fmaf(P_F32(76), yn, P_F32(68));
                    const F4 f = tex_rgba(tex, u, v);
#endif
                    v0 = fmaf(rw, r0, fmaf(f.x, 0.125f, -0.0625f));
                    v1 = fmaf(rw, r1, fmaf(f.y, 0.125f, -0.0625f));
                    v2 = fmaf(rw, r2, fmaf(f.z, 0.125f, -0.0625f));
                } else {
                    v0 = rw * r0; v1 = rw * r1; v2 = rw * r2;
                }
                if (final_clamp) {
                    v0 = fminf(1.0f, fmaxf(0.0f, fmaf(v0, 8.0f, 0.5f)));
                    v1 = fminf(1.0f, fmaxf(0.0f, fmaf(v1, 8.0f, 0.5f)));
                    v2 = fminf(1.0f, fmaxf(0.0f, fmaf(v2, 8.0f, 0.5f)));
                    alpha = 1.0f;
                }
                // temporal accumulation (F0 43905-44084): blend weight from +104 (float16, inf -> 0, clamped to [0, 1]),
                // only after the final clamp, with history (+88) and motion (+96); +112: motion vectors present
#if TEMPORAL_PAIR
                if (temporal) {
                    const float a = fminf(1.0f, fmaxf(0.0f, rcp_approx(ex2a(r3 * -1.44269502162933350f) + 1.0f) * bw0));
                    v0 = fmaf(a, fmaf(hsp[pass].x, hnp[pass], -v0), v0);
                    v1 = fmaf(a, fmaf(hsp[pass].y, hnp[pass], -v1), v1);
                    v2 = fmaf(a, fmaf(hsp[pass].z, hnp[pass], -v2), v2);
                }
#else
                float bw = 1.0f;
                if (bscale != 0ull) {
                    const float b = h16_to_f32(*(const u16*)bscale);
                    bw = fabsf(b) == __int_as_float(0x7F800000) ? 0.0f : fminf(1.0f, fmaxf(0.0f, b));
                }
                if (!NO_TEMPORAL && final_clamp && hist != 0ull && bw > 0.0f && mot != 0ull) {
                    const F4 mv = tex_rgba(mot, P_F32(156) * fmaf(P_F32(148), xn, P_F32(140)), P_F32(160) * fmaf(P_F32(152), yn, P_F32(144)));
                    const bool have = P_S32(112) != 0;
                    const float qx = have ? fmaf(P_F32(164), mv.x, xn) : xn, qy = have ? fmaf(P_F32(168), mv.y, yn) : yn;  // fmaf: as the PTX
                    const float fcf = (float)fcols, frf = (float)frows;
                    F4 hs; float hn;
                    history5(hist, qx, qy, fcf, frf, fcf - 0.5f, frf - 0.5f, rcp_approx(fcf), rcp_approx(frf),
                             P_F32(124), P_F32(116), P_F32(132), P_F32(128), P_F32(120), P_F32(136), hs, hn);
                    const float a = fminf(1.0f, fmaxf(0.0f, rcp_approx(ex2a(r3 * -1.44269502162933350f) + 1.0f) * bw));
                    v0 = fmaf(a, fmaf(hs.x, hn, -v0), v0);              // (s * r - v): ptxas folded the mul (SASS: FFMA)
                    v1 = fmaf(a, fmaf(hs.y, hn, -v1), v1);
                    v2 = fmaf(a, fmaf(hs.z, hn, -v2), v2);
                }
#endif
                asm volatile("sust.p.2d.v4.b32.zero [%0, {%1, %2}], {%3, %4, %5, %6};"
                             :: "l"(surf), "r"(px), "r"(py), "f"(v0), "f"(v1), "f"(v2), "f"(alpha) : "memory");
        }
    }
    { // balances the common output scope below
#endif
    }
}
